use std::fs

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct Rtri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}

impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}

impl Shape for Rtri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}

impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn report(s: Box<dyn Shape>) -> int {
    println("${s.name()} corners=${s.corners()} area2=${s.double_area()}")
    s.double_area()
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total: int = 0
    let mut best: int = -1
    let mut best_name = "none"
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let kind = parts[0]
        let mut nums: Vec<int> = []
        let mut i = 1
        while i < parts.len() {
            nums.push(parts[i].parse::<int>().unwrap_or(0))
            i += 1
        }
        let shape: Box<dyn Shape> = if kind == "square" {
            Box::new(Square { s: nums[0] })
        } else if kind == "rect" {
            Box::new(Rect { w: nums[0], h: nums[1] })
        } else if kind == "rtri" {
            Box::new(Rtri { a: nums[0], b: nums[1] })
        } else {
            Box::new(Trap { a: nums[0], b: nums[1], h: nums[2] })
        }
        let d = report(shape)
        total += d
        if d > best {
            best = d
            best_name = kind
        }
    }
    if best < 0 {
        println("total area2=0")
        println("largest=none")
    } else {
        println("total area2=${total}")
        println("largest=${best_name} area2=${best}")
    }
}

